python3 - <<'PY'
import json
r=json.load(open('/tmp/research_runtime.json'))
print('TOP KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k, json.dumps(v,ensure_ascii=False))
c=r['context']; print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge_access_log']: print(k,json.dumps(v,ensure_ascii=False)[:24000])
print('HISTORY SUMMARY')
for h in c.get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k"'!='"'validation'},ensure_ascii=False))
 print('validation',json.dumps({k:v for k,v in h.get('validation',{}).items() if k not in ['slices','per_task']},ensure_ascii=False))
PY"

